package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Enter full-screen linear TV without requiring a catalog detour. */
public final class TvModeActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle state){super.onCreate(state);MyIptvRepository.refreshInBackground(this);ZbdsRepository.refreshInBackground(this);LinearLayout root=TvUi.root(this);root.addView(TvUi.title(this,"电视模式",28));TextView status=TvUi.text(this,"正在准备频道…",18,TvUi.MUTED);root.addView(status);worker.execute(()->{try{List<CatalogItem> channels=new ArrayList<>();for(CatalogItem item:new CatalogRepository(this).load())if(item.live()&&item.mode.equals("stream"))channels.add(item);Collections.sort(channels,(a,b)->{int region=Boolean.compare(a.section.equals("foreign"),b.section.equals("foreign"));return region!=0?region:Boolean.compare(a.title.matches(".*(4K|8K).*"),b.title.matches(".*(4K|8K).*"));});if(channels.isEmpty())throw new java.io.IOException("暂无直接播放频道，请在设置中导入直播列表。");String last=getSharedPreferences("settings",0).getString("last_tv","");ArrayList<String> ids=new ArrayList<>();int selected=0;for(int n=0;n<channels.size();n++){ids.add(channels.get(n).id);if(channels.get(n).id.equals(last))selected=n;}final int index=selected;runOnUiThread(()->{if(isDestroyed())return;startActivity(new Intent(this,PlayerActivity.class).putStringArrayListExtra("ids",ids).putExtra("index",index).putExtra("tv_mode",true));finish();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;status.setText(e.getMessage());Button settings=TvUi.button(this,"导入直播源");root.addView(settings);settings.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));});}});}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
